css:
.dighotel-sim-container {
    padding: 20px;
    background: linear-gradient(135deg, #eef2f7 0%, #dce6f0 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}
.dighotel-sim-container .dighotel-sim-header {
    background: linear-gradient(135deg, #1a5276 0%, #2471a3 100%);
    color: white;
    padding: 30px;
    border-radius: 20px;
    margin-bottom: 30px;
    box-shadow: 0 8px 16px rgba(0,0,0,0.15);
    text-align: center;
}
.dighotel-sim-container .dighotel-sim-header h1 { margin: 0 0 5px 0; font-size: 1.8rem; }
.dighotel-sim-container .dighotel-sim-header p { margin: 0; opacity: 0.9; font-size: 1rem; }
.dighotel-sim-container .dighotel-sim-period-counter {
    text-align: center;
    font-size: 1.2rem;
    margin-bottom: 20px;
    color: #555;
}
.dighotel-sim-container .dighotel-sim-status-cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
    gap: 15px;
    margin-bottom: 25px;
}
.dighotel-sim-container .dighotel-sim-status-card {
    background: white;
    border-radius: 12px;
    padding: 18px 15px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
    text-align: center;
    transition: transform 0.3s ease;
}
.dighotel-sim-container .dighotel-sim-status-card:hover { transform: translateY(-3px); }
.dighotel-sim-container .dighotel-sim-label {
    color: #666;
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: 6px;
}
.dighotel-sim-container .dighotel-sim-value {
    font-size: 1.5rem;
    font-weight: 700;
    color: #333;
}
.dighotel-sim-container .dighotel-card-budget .dighotel-sim-value { color: #2471a3; }
.dighotel-sim-container .dighotel-card-roi .dighotel-sim-value { color: #27ae60; }
.dighotel-sim-container .dighotel-card-score .dighotel-sim-value { color: #8e44ad; }
.dighotel-sim-container .dighotel-sim-briefing {
    background: #fef9e7;
    border-left: 4px solid #f39c12;
    border-radius: 8px;
    padding: 15px 20px;
    margin-bottom: 25px;
    font-size: 0.95rem;
    color: #7d6608;
}
.dighotel-sim-container .dighotel-sim-controls {
    background: white;
    border-radius: 15px;
    padding: 25px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
    margin-bottom: 25px;
}
.dighotel-sim-container .dighotel-sim-controls h3 { margin-top: 0; color: #1a5276; }
.dighotel-sim-container .dighotel-sim-budget-tracker {
    background: #eaf2f8;
    border-radius: 8px;
    padding: 10px 15px;
    margin-bottom: 15px;
    font-size: 0.95rem;
    color: #1a5276;
}
.dighotel-sim-container .dighotel-sim-inv-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(290px, 1fr));
    gap: 12px;
    margin-bottom: 20px;
}
.dighotel-sim-container .dighotel-sim-inv-card {
    border: 2px solid #ddd;
    border-radius: 10px;
    padding: 12px;
    transition: all 0.2s ease;
    cursor: pointer;
    background: #fafafa;
}
.dighotel-sim-container .dighotel-sim-inv-card:hover { border-color: #2471a3; background: #f0f7fc; }
.dighotel-sim-container .dighotel-sim-inv-card.dighotel-checked { border-color: #2471a3; background: #eaf2f8; }
.dighotel-sim-container .dighotel-sim-inv-card.dighotel-purchased {
    border-color: #27ae60; background: #eafaf1; opacity: 0.75; cursor: default;
}
.dighotel-sim-container .dighotel-sim-inv-card.dighotel-purchased:hover { border-color: #27ae60; background: #eafaf1; }
.dighotel-sim-container .dighotel-sim-inv-card label {
    display: flex; align-items: flex-start; gap: 10px; cursor: pointer; margin: 0;
}
.dighotel-sim-container .dighotel-sim-inv-card.dighotel-purchased label { cursor: default; }
.dighotel-sim-container .dighotel-inv-info { flex: 1; }
.dighotel-sim-container .dighotel-inv-name { display: block; font-weight: 600; color: #333; margin-bottom: 4px; font-size: 0.92rem; }
.dighotel-sim-container .dighotel-inv-detail { display: block; font-size: 0.78rem; color: #666; line-height: 1.4; }
.dighotel-sim-container .dighotel-inv-badges { display: flex; gap: 6px; flex-wrap: wrap; margin-top: 6px; }
.dighotel-sim-container .dighotel-badge {
    display: inline-block; padding: 2px 8px; border-radius: 4px; font-size: 0.72rem; font-weight: 600;
}
.dighotel-sim-container .dighotel-risk-low { background: #d5f5e3; color: #1e8449; }
.dighotel-sim-container .dighotel-risk-medium { background: #fdebd0; color: #b9770e; }
.dighotel-sim-container .dighotel-risk-high { background: #fadbd8; color: #c0392b; }
.dighotel-sim-container .dighotel-prereq-met { color: #27ae60; font-size: 0.78rem; }
.dighotel-sim-container .dighotel-prereq-unmet { color: #e74c3c; font-size: 0.78rem; }
.dighotel-sim-container .dighotel-purchased-tag {
    background: #27ae60; color: white; padding: 2px 8px; border-radius: 4px; font-size: 0.72rem; font-weight: 600;
}
.dighotel-sim-container .dighotel-sim-scorecard {
    background: white;
    border-radius: 15px;
    padding: 25px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
    margin-bottom: 25px;
}
.dighotel-sim-container .dighotel-sim-scorecard h3 { margin-top: 0; color: #1a5276; }
.dighotel-sim-container .dighotel-score-row {
    display: flex; align-items: center; margin-bottom: 10px; gap: 10px;
}
.dighotel-sim-container .dighotel-score-label { width: 170px; font-size: 0.85rem; color: #555; }
.dighotel-sim-container .dighotel-score-weight { width: 40px; font-size: 0.72rem; color: #999; text-align: right; }
.dighotel-sim-container .dighotel-score-bar-bg {
    flex: 1; height: 20px; background: #ecf0f1; border-radius: 10px; overflow: hidden;
}
.dighotel-sim-container .dighotel-score-bar-fill {
    height: 100%; border-radius: 10px; transition: width 0.5s ease;
}
.dighotel-sim-container .dighotel-score-val { width: 40px; text-align: right; font-weight: 600; font-size: 0.85rem; }
.dighotel-sim-container .dighotel-sim-history { margin-bottom: 25px; }
.dighotel-sim-container .dighotel-sim-chart {
    background: white;
    border-radius: 15px;
    padding: 20px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
    height: 300px;
}
@media (max-width: 768px) {
    .dighotel-sim-container .dighotel-sim-status-cards { grid-template-columns: repeat(2, 1fr); }
    .dighotel-sim-container .dighotel-sim-inv-grid { grid-template-columns: 1fr; }
    .dighotel-sim-container .dighotel-score-label { width: 110px; font-size: 0.75rem; }
}

