        getPerformanceSummary(history) {
            if (!history.length) return {};
            var lastEntry = history[history.length - 1];
            var ds = window.mySimulation.state.domainState;
            var totalInvested = ds.cumulativeInvestment;
            var totalROI = ds.cumulativeROI;
            var netValue = ds.netValue;
            var overall = ds.overallScore;

            var performance = 'Beginner Portfolio Manager';
            if (overall >= 40) performance = 'Competent Technology Strategist';
            if (overall >= 60) performance = 'Strong Portfolio Optimizer';
            if (overall >= 80) performance = 'Excellent CTO Material';

            var insights = [];
            if (ds.purchased.indexOf(11) === -1) {
                insights.push('Cybersecurity was overlooked. Expected breach costs reduced overall returns significantly.');
            }
            if (ds.purchased.indexOf(10) === -1) {
                insights.push('Without a training platform, technology adoption rates were low, reducing ROI on complex systems by up to 50%.');
            }
            if (ds.purchased.indexOf(1) !== -1 && ds.purchased.indexOf(3) !== -1 && ds.purchased.indexOf(4) !== -1) {
                insights.push('Good foundation: PMS + Direct Booking + CRM creates a powerful guest acquisition engine.');
            }
            if (ds.purchased.indexOf(6) !== -1 && ds.purchased.indexOf(5) !== -1) {
                insights.push('RMS + Dynamic Pricing synergy captured maximum revenue optimization potential.');
            }
            if (netValue > 400000) {
                insights.push('Outstanding net value creation. Well-balanced portfolio with strong financial returns.');
            }
            if (ds.maturityLevel >= 4) {
                insights.push('Advanced technology maturity achieved. Hotel Mirador is well-positioned for the future.');
            }
            if (insights.length === 0) {
                insights.push('Consider how dependency management and change management affect technology ROI.');
            }

            return {
                totalInvested: totalInvested,
                totalROI: totalROI,
                netValue: netValue,
                maturityLevel: ds.maturityLevel,
                overallScore: overall,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            var ds = state.domainState;
            if (ds.purchased.indexOf(11) === -1) {
                return window.mySimulation.t('hint_no_cyber');
            }
            if (ds.purchased.indexOf(10) === -1 && ds.purchased.length >= 3) {
                return window.mySimulation.t('hint_no_training');
            }
            if (ds.purchased.indexOf(1) === -1 && state.currentPeriod >= 2) {
                return window.mySimulation.t('hint_no_pms');
            }
            if (ds.overallScore >= 50) {
                return window.mySimulation.t('hint_good');
            }
            return null;
        }

